sys_script_include.script:
var CourseUtil = Class.create();
CourseUtil.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getFilterEnrollment: function() {

        var user = 'opened_by';
        var date = 'date';

        var userSysID = gs.getUserID();
        var selectedCourseSysID = current.variables.course;

        var schedulesToExclude = [];

        if (!selectedCourseSysID) {
            return;
        }

        var gr = new GlideRecord('x_752538_course_enrollment');
        gr.addQuery(user, userSysID);
        gr.addQuery('course', selectedCourseSysID);
        gr.query();

		while (gr.next()) {
            schedulesToExclude.push(gr.getValue(date));
        }

        var finalFilter = 'date' + selectedCourseSysID; 

        if (schedulesToExclude.length > 0) {
            finalFilter += '^sys_idNOT IN' + schedulesToExclude.join(',');
        }

        return finalFilter;
    },

    type: 'CourseUtil'
});
